#[cfg(test)]
mod tests {
    use rigorix_engine::effect_commitment::application::NodeStateVocabulary;
    use rigorix_engine::effect_commitment::domain::EffectState;
    use rigorix_engine::state_persistence::domain::NodeStatus;

    #[test]
    fn test_nodestatevocabulary_is_defined() {
        assert_eq!(NodeStateVocabulary::DISPATCHED, "dispatched");
        assert_eq!(NodeStateVocabulary::AMBIGUOUS, "ambiguous");
        assert_eq!(NodeStateVocabulary::new(), NodeStateVocabulary);
    }

    #[test]
    fn test_nodestatevocabulary_interacts_with_effectstate() {
        // The two new node words map to the two non-terminal effect states.
        assert_eq!(
            NodeStateVocabulary::effect_state_for("dispatched"),
            Some(EffectState::Dispatched)
        );
        assert_eq!(
            NodeStateVocabulary::effect_state_for("ambiguous"),
            Some(EffectState::Ambiguous)
        );
        assert_eq!(NodeStateVocabulary::effect_state_for("completed"), None);

        // Neither new word is terminal: an unknown outcome must not be recorded
        // as Completed or Failed.
        assert!(!NodeStateVocabulary::is_terminal("dispatched"));
        assert!(!NodeStateVocabulary::is_terminal("ambiguous"));
        assert!(NodeStateVocabulary::is_terminal("completed"));
        assert!(NodeStateVocabulary::is_terminal("failed"));

        // Terminal commitment reuses the existing node vocabulary.
        assert_eq!(
            NodeStateVocabulary::label(EffectState::Committed),
            "completed"
        );
        assert_eq!(
            NodeStateVocabulary::label(EffectState::NotCommitted),
            "failed"
        );
        assert_eq!(
            NodeStateVocabulary::label(EffectState::Ambiguous),
            NodeStateVocabulary::AMBIGUOUS
        );

        // The cross-context edit: state_persistence now carries the same words,
        // and both new variants are non-terminal.
        assert_eq!(
            NodeStatus::Dispatched.as_str(),
            NodeStateVocabulary::DISPATCHED
        );
        assert_eq!(
            NodeStatus::Ambiguous.as_str(),
            NodeStateVocabulary::AMBIGUOUS
        );
        assert!(!NodeStatus::Dispatched.is_terminal());
        assert!(!NodeStatus::Ambiguous.is_terminal());
        assert!(NodeStatus::Ambiguous.is_ambiguous());
        assert!(NodeStatus::Dispatched.is_unsettled());
        assert!(NodeStatus::Ambiguous.is_unsettled());
    }
}
